# GRAFICO DE LINHA
with tab_linha:
    st.subheader('teste criação de grafico de linha')
    valorxl = st.text_input('digite os valores para x (ex: 0,1,2,3,4) (exemplo de dado: Tempo)')
    valoryl = st.text_input('digite os valores para y (ex: 0,1,2,3,4) (exemplo de dado: faturamento)')

    st.markdown("""
    <style>
    /* Texto input preto */
    .stTextInput > div > div > input {
        color: black !important;
        caret-color: black !important; /* Cursor também preto */
    }

    /* Placeholder cinza escuro */
    .stTextInput > div > div > input::placeholder {
        color: #666 !important;
    }

    /* Label input escuro */
    .stTextInput > label {
        color: #333 !important;
    }
    </style>
    """, unsafe_allow_html=True)


    if st.button('gerar grafico'):
        try:
            x = ast.literal_eval(valorxl)
            y = ast.literal_eval(valoryl)
            if len(x) == len(y):
                fig, ax = plt.subplots(figsize=(5,3))
                ax.plot(x, y, marker = 'o', linestyle='-', color='blue')
                ax.set_title('seu grafico personalizado')
                ax.set_xlabel('X')
                ax.set_ylabel('Y')
                ax.grid(True)
                st.pyplot(fig, use_container_width= False)
            else:
                st.error('listas de Y e X devem ter o mesmo tamanho!')
        except:
            st.error('formato invalido! use listas como [1,2,3]')

# GRAFICO DE BARRA
with tab_bar:
    st.subheader('teste criação de gráfico de barras')

    valorx5 = st.text_input(
        'digite os valores para x (ex: ["Produto A","Produto B","Produto C"]) (exemplo de dado: nomes das categorias)',
        key='barras_x'
    )

    valory5 = st.text_input(
        'digite os valores para y (ex: [5,10,15]) (exemplo de dado: valores em dinheiro ou quantidade)',
        key='barras_y'
    )

    if st.button('gerar gráfico', key='btn_barras'):
        try:
            x = ast.literal_eval(valorx5)
            y = ast.literal_eval(valory5)

            if len(x) == len(y):
                fig, ax = plt.subplots(figsize=(5, 3))
                ax.barh(x, y, color='orange')
                ax.set_title('seu gráfico de barras')
                ax.set_xlabel('Y')
                ax.set_ylabel('X')
                ax.grid(axis='x')
                st.pyplot(fig, use_container_width=False)
            else:
                st.error('listas de x e y devem ter o mesmo tamanho!')
        except:
            st.error('formato inválido! use listas como ["A","B","C"] e [1,2,3]') 

# GRÁFICO DE PIZZA
with tab_pizza:
    st.subheader('teste criação de gráfico de pizza')
    rotulos = st.text_input('digite os rótulos (ex: ["A","B","C"]) (exemplo de dado: despesas)')
    valores = st.text_input('digite os valores (ex: [10,20,30]) (exemplo de dado: valores)')

    if st.button('gerar gráfico', key='btn_pizza'):
        try:
            labels = ast.literal_eval(rotulos)
            sizes = ast.literal_eval(valores)

            if len(labels) == len(sizes):
                fig, ax = plt.subplots(figsize=(6,4))
                ax.pie(sizes, labels=labels)
                ax.set_title('seu gráfico de pizza')
                st.pyplot(fig, use_container_width= False)
            else:
                st.error('listas de rótulos e valores devem ter o mesmo tamanho!')
        except:
            st.error('formato inválido! use listas como ["A","B","C"] e [10,20,30]')

